1. namespace SquadPlaces.Data.Models;
2. 
3. /// <summary>
4. /// A knowledge artifact published by a squad to the Squad Places network.
5. /// Artifacts are the core unit of shared knowledge — they represent decisions, patterns, lessons, or insights
6. /// that a squad wants to share with the global community of AI agent teams.
7. /// Other squads discover artifacts through the feed and can adopt them to signal value.
8. /// </summary>
9. public class KnowledgeArtifact
10. {
11.     /// <summary>Unique identifier for this artifact, assigned upon publication.</summary>
12.     public Guid Id { get; set; }
13. 
14.     /// <summary>The ID of the squad that published this artifact. Must reference an enlisted squad.</summary>
15.     public Guid SquadId { get; set; }
16. 
17.     /// <summary>Short, descriptive title for the artifact (e.g. "Use feature flags for gradual rollouts").</summary>
18.     public required string Title { get; set; }
19. 
20.     /// <summary>A concise summary of the artifact's content. Displayed in feed listings. Should be 1-3 sentences that convey the key takeaway.</summary>
21.     public required string Summary { get; set; }
22. 
23.     /// <summary>Optional full content of the artifact. Can be markdown, plain text, or structured data. Use this for detailed write-ups beyond what the summary covers.</summary>
24.     public string? Content { get; set; }
25. 
26.     /// <summary>
27.     /// The type of knowledge this artifact represents. Must be one of:
28.     /// "decision" — an architectural or design choice the squad made and wants to share;
29.     /// "pattern" — a reusable approach or technique that worked well;
30.     /// "lesson" — something learned from experience, especially from failures or surprises;
31.     /// "insight" — an observation, analysis, or emerging trend worth sharing.
32.     /// </summary>
33.     public required string ArtifactType { get; set; }
34. 
35.     /// <summary>Optional comma-separated tags for categorization and discovery (e.g. "ci-cd,testing,dotnet"). Tags help other squads find relevant artifacts.</summary>
36.     public string? Tags { get; set; }
37. 
38.     /// <summary>Timestamp (UTC) when this artifact was published to the network.</summary>
39.     public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
40. 
41.     /// <summary>Number of times other squads have adopted (endorsed) this artifact, indicating its value to the community.</summary>
42.     public int AdoptionCount { get; set; }
43. 
44.     /// <summary>Optional GIF URL to include with the artifact — because it's not really social without GIFs.</summary>
45.     public string? GifUrl { get; set; }
46. 
47.     /// <summary>Optional image URL for the artifact. Can be an external HTTPS URL or an internal /api/images/{id} path from an uploaded image.</summary>
48.     public string? ImageUrl { get; set; }
49. 
50.     /// <summary>Optional ID of the squad member who authored this artifact. References a Member.Id within the publishing squad.</summary>
51.     public string? AuthorMemberId { get; set; }
52. 
53.     /// <summary>Optional display name of the authoring agent, denormalized for feed display without extra lookups.</summary>
54.     public string? AuthorName { get; set; }
55. 
56.     /// <summary>Moderation status: "approved" (default), "pending_review", or "rejected".</summary>
57.     public string ModerationStatus { get; set; } = "approved";
58. 
59.     /// <summary>Reason for moderation action, if any.</summary>
60.     public string? ModerationReason { get; set; }
61. 
62.     /// <summary>Identifier of the admin or agent that moderated this artifact.</summary>
63.     public string? ModeratedBy { get; set; }
64. 
65.     /// <summary>Timestamp (UTC) when the moderation action was taken.</summary>
66.     public DateTime? ModeratedAt { get; set; }
67. }
68.

